ALTER TABLE public.lesson_questions
  ADD COLUMN IF NOT EXISTS options_fr text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS options_en text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS correct_index integer;

ALTER TABLE public.answers
  ADD COLUMN IF NOT EXISTS choice_index integer;

WITH data(lp, qp, ci, fr, en) AS (
  VALUES
  (1,1,0,ARRAY['Elle est inspirée de Dieu et utile pour enseigner et corriger','Elle a été écrite par des sages pour instruire les rois','Elle est un recueil de légendes utile aux historiens'],ARRAY['It is inspired by God and useful for teaching and correcting','It was written by wise men to instruct kings','It is a collection of legends useful to historians']),
  (1,2,0,ARRAY['Poussés par le Saint-Esprit, et non par leur propre volonté','Par des rêves qu''ils interprétaient librement','En recopiant les traditions de leur peuple'],ARRAY['Moved by the Holy Spirit, not by their own will','Through dreams they interpreted freely','By copying the traditions of their people']),
  (1,3,0,ARRAY['À une lampe et une lumière sur le sentier','À un trésor caché dans un champ','À un mur qui protège la ville'],ARRAY['To a lamp and a light on the path','To treasure hidden in a field','To a wall protecting the city']),
  (1,4,0,ARRAY['Elle est la vérité, et elle sanctifie','Elle est un mystère réservé aux prêtres','Elle a été remplacée par la tradition'],ARRAY['It is truth, and it sanctifies','It is a mystery reserved for priests','It has been replaced by tradition']),
  (2,1,0,ARRAY['Tête d''or, poitrine d''argent, ventre d''airain, jambes de fer, pieds de fer et d''argile','Une statue entièrement d''or, brisée par le vent','Un arbre immense couvert de fruits'],ARRAY['Head of gold, chest of silver, belly of bronze, legs of iron, feet of iron and clay','A statue entirely of gold, broken by the wind','A huge tree covered with fruit']),
  (2,2,0,ARRAY['Babylone, la Médo-Perse, la Grèce et Rome','L''Égypte, l''Assyrie, Israël et Juda','Rome, la France, l''Espagne et l''Angleterre'],ARRAY['Babylon, Medo-Persia, Greece and Rome','Egypt, Assyria, Israel and Judah','Rome, France, Spain and England']),
  (2,3,0,ARRAY['Un royaume établi par Dieu, qui ne sera jamais détruit','Un empire mondial dirigé par un homme sage','Une alliance de dix nations européennes'],ARRAY['A kingdom set up by God that will never be destroyed','A world empire led by a wise man','An alliance of ten European nations']),
  (2,4,0,ARRAY['Le songe vient de Dieu lui-même et son interprétation est certaine','Nebucadnetsar l''a confirmée par un décret','Les sages de Babylone l''ont vérifiée'],ARRAY['The dream comes from God himself and its meaning is sure','Nebuchadnezzar confirmed it by decree','The wise men of Babylon verified it']),
  (3,1,0,ARRAY['De nouveaux cieux et une nouvelle terre','Un nouveau temple à Jérusalem','Une nouvelle alliance avec l''Égypte'],ARRAY['New heavens and a new earth','A new temple in Jerusalem','A new covenant with Egypt']),
  (3,2,0,ARRAY['La mort, le deuil, les cris et la douleur','Les nations et les langues','Le travail et le repos'],ARRAY['Death, mourning, crying and pain','Nations and languages','Work and rest']),
  (3,3,0,ARRAY['Les aveugles voient, les sourds entendent, les boiteux sautent','Les hommes deviennent invisibles','Les corps restent inchangés'],ARRAY['The blind see, the deaf hear, the lame leap','People become invisible','Bodies remain unchanged']),
  (3,4,0,ARRAY['Il attend ce monde nouveau avec espérance','Il s''en désintéresse','Il essaie d''en fixer la date'],ARRAY['He waits for that new world in hope','He loses interest in it','He tries to fix its date']),
  (4,1,0,ARRAY['Il prépare une place et revient chercher les siens','Il promet la richesse à ses disciples','Il annonce qu''il ne reviendra jamais'],ARRAY['He prepares a place and comes back for his own','He promises his disciples riches','He says he will never return']),
  (4,2,0,ARRAY['De la même manière qu''il est monté au ciel','Secrètement, dans le désert','Par la voix d''un prophète'],ARRAY['In the same way he went up into heaven','Secretly, in the wilderness','Through the voice of a prophet']),
  (4,3,0,ARRAY['Visible comme l''éclair, d''orient en occident','Discret, connu de quelques élus','Uniquement spirituel, dans le cœur'],ARRAY['Visible as lightning, from east to west','Quiet, known to a few chosen ones','Only spiritual, within the heart']),
  (4,4,0,ARRAY['Les morts en Christ ressuscitent, puis les vivants sont enlevés','Les croyants restent sur la terre mille ans','Chacun est jugé séparément après sa mort'],ARRAY['The dead in Christ rise, then the living are caught up','Believers stay on earth a thousand years','Each is judged separately right after dying']),
  (5,1,0,ARRAY['Des guerres, des famines et des tremblements de terre','Une paix mondiale durable','La disparition des nations'],ARRAY['Wars, famines and earthquakes','Lasting world peace','The disappearance of nations']),
  (5,2,0,ARRAY['L''égoïsme, l''amour de l''argent, une piété d''apparence','Une générosité universelle','Le silence des faux docteurs'],ARRAY['Selfishness, love of money, a religion of appearance','Universal generosity','The silence of false teachers']),
  (5,3,0,ARRAY['L''Évangile prêché dans le monde entier','La reconstruction du temple','L''unité de tous les gouvernements'],ARRAY['The gospel preached in all the world','The rebuilding of the temple','The union of all governments']),
  (5,4,0,ARRAY['Personne ne les connaît, sinon le Père','Les prophètes les ont calculés','Ils sont écrits dans le livre de Daniel'],ARRAY['No one knows them but the Father','The prophets calculated them','They are written in the book of Daniel']),
  (6,1,0,ARRAY['Les cieux racontent la gloire de Dieu','La création ne dit rien de Dieu','Seul le temple révèle Dieu'],ARRAY['The heavens declare the glory of God','Creation says nothing about God','Only the temple reveals God']),
  (6,2,0,ARRAY['Ses œuvres rendent ses perfections invisibles visibles','Parce que la loi romaine le proclamait','Parce que les philosophes l''avaient prouvé'],ARRAY['His works make his invisible qualities visible','Because Roman law proclaimed it','Because philosophers had proved it']),
  (6,3,0,ARRAY['Dieu est amour','Dieu est colère','Dieu est silence'],ARRAY['God is love','God is anger','God is silence']),
  (6,4,0,ARRAY['Celui qui cherche de tout son cœur le trouvera','Seuls les prêtres peuvent le trouver','Il restera toujours caché'],ARRAY['Whoever seeks him with all their heart will find him','Only priests can find him','He will always stay hidden']),
  (7,1,0,ARRAY['Parfait dans ses voies dès le jour de sa création','Mauvais depuis toujours','Un simple roi de Tyr, sans plus'],ARRAY['Perfect in his ways from the day he was created','Evil from the very beginning','Merely a king of Tyre, nothing more']),
  (7,2,0,ARRAY['L''orgueil : il a voulu être semblable au Très-Haut','La paresse','L''ignorance de la loi'],ARRAY['Pride: he wanted to be like the Most High','Laziness','Ignorance of the law']),
  (7,3,0,ARRAY['Une guerre : le dragon a été précipité sur la terre','Un accord de paix','Une longue période de silence'],ARRAY['A war: the dragon was cast down to the earth','A peace agreement','A long period of silence']),
  (7,4,0,ARRAY['Se soumettre à Dieu et résister au diable','Négocier avec la tentation','Fuir toute vie sociale'],ARRAY['Submit to God and resist the devil','Negotiate with temptation','Avoid all social life']),
  (8,1,0,ARRAY['Elle était Dieu, et toutes choses ont été faites par elle','Elle est une créature parmi d''autres','Elle est apparue seulement à Bethléem'],ARRAY['He was God, and all things were made through him','He is one creature among others','He first existed at Bethlehem']),
  (8,2,0,ARRAY['Nos souffrances et nos péchés','Ses propres fautes','Les dettes du peuple romain'],ARRAY['Our sufferings and our sins','His own faults','The debts of the Roman people']),
  (8,3,0,ARRAY['Il a été tenté comme nous, mais sans pécher','Il n''a jamais connu la faiblesse','Il a vécu loin des hommes'],ARRAY['He was tempted as we are, yet without sin','He never knew weakness','He lived far away from people']),
  (8,4,0,ARRAY['L''amour : il a donné son Fils unique','La crainte du désordre','Le besoin d''obéissance'],ARRAY['Love: he gave his only Son','Fear of disorder','A need for obedience']),
  (9,1,0,ARRAY['Le péché est la transgression de la loi','Le péché est une simple maladresse','Le péché est une invention humaine'],ARRAY['Sin is the transgression of the law','Sin is a simple mistake','Sin is a human invention']),
  (9,2,0,ARRAY['Tous ont péché','Seuls les incroyants','Seuls ceux qui ignorent la loi'],ARRAY['All have sinned','Only unbelievers','Only those who do not know the law']),
  (9,3,0,ARRAY['Il sépare de Dieu et cache sa face','Il n''a aucun effet','Il rapproche de Dieu'],ARRAY['It separates from God and hides his face','It has no effect','It brings us closer to God']),
  (9,4,0,ARRAY['Il pardonne et purifie de toute iniquité','Il attend une longue pénitence','Il oublie sans pardonner'],ARRAY['He forgives and cleanses from all unrighteousness','He waits for a long penance','He forgets without forgiving']),
  (10,1,0,ARRAY['Se repentir et se convertir','Jeûner et payer','Étudier et enseigner'],ARRAY['Repent and turn back to God','Fast and pay','Study and teach']),
  (10,2,0,ARRAY['Un cœur nouveau et un esprit nouveau','Une nouvelle nationalité','Une meilleure santé seulement'],ARRAY['A new heart and a new spirit','A new nationality','Better health only']),
  (10,3,0,ARRAY['Il court vers lui, l''embrasse et le reçoit','Il le renvoie','Il exige un remboursement'],ARRAY['He runs to him, embraces him and welcomes him','He sends him away','He demands repayment']),
  (10,4,0,ARRAY['Il frappe à la porte et attend qu''on ouvre','Il entre de force','Il passe sans s''arrêter'],ARRAY['He knocks at the door and waits to be let in','He forces his way in','He passes by without stopping']),
  (11,1,0,ARRAY['Naître de nouveau, d''eau et d''Esprit','Être né dans une famille croyante','Connaître la loi par cœur'],ARRAY['Be born again, of water and Spirit','Be born into a believing family','Know the law by heart']),
  (11,2,0,ARRAY['Une nouvelle créature','Un homme sans épreuves','Un maître de la loi'],ARRAY['A new creation','Someone without trials','A master of the law']),
  (11,3,0,ARRAY['Ce n''est plus lui qui vit, mais Christ en lui','Il vit selon ses propres forces','Il attend la mort sans espérance'],ARRAY['It is no longer he who lives, but Christ in him','He lives by his own strength','He awaits death without hope']),
  (11,4,0,ARRAY['Sur la miséricorde de Dieu, non sur nos œuvres','Sur nos bonnes actions','Sur notre origine familiale'],ARRAY['On God''s mercy, not on our works','On our good deeds','On our family background']),
  (12,1,0,ARRAY['Quatre commandements sur la relation à Dieu, six sur la relation au prochain','Dix règles de purification','Dix conseils facultatifs'],ARRAY['Four commandments about God, six about our neighbour','Ten rules of purification','Ten optional pieces of advice']),
  (12,2,0,ARRAY['Aimer Dieu de tout son cœur et son prochain comme soi-même','Offrir des sacrifices chaque jour','Se séparer des étrangers'],ARRAY['Love God with all your heart and your neighbour as yourself','Offer sacrifices every day','Separate from foreigners']),
  (12,3,0,ARRAY['Non : il est venu l''accomplir','Oui : il l''a supprimée','Il n''en a rien dit'],ARRAY['No: he came to fulfil it','Yes: he abolished it','He said nothing about it']),
  (12,4,0,ARRAY['La foi ne détruit pas la loi, elle la confirme','La foi rend la loi inutile','La loi remplace la foi'],ARRAY['Faith does not destroy the law, it confirms it','Faith makes the law useless','The law replaces faith']),
  (13,1,0,ARRAY['Il s''est reposé, puis il a béni et sanctifié ce jour','Il a créé les animaux','Il a donné la loi à Moïse'],ARRAY['He rested, then blessed and sanctified that day','He created the animals','He gave the law to Moses']),
  (13,2,0,ARRAY['Se souvenir du septième jour pour le sanctifier','Choisir un jour quelconque','Travailler sans interruption'],ARRAY['Remember the seventh day to keep it holy','Choose any day at all','Work without stopping']),
  (13,3,0,ARRAY['Il entrait à la synagogue le jour du sabbat, selon sa coutume','Il évitait les réunions','Il enseignait seulement en semaine'],ARRAY['He went into the synagogue on the Sabbath, as was his custom','He avoided gatherings','He taught only on weekdays']),
  (13,4,0,ARRAY['Pour l''homme ; et le Fils de l''homme en est le maître','Pour les prêtres uniquement','Pour les anges'],ARRAY['For humanity; and the Son of Man is its Lord','For priests only','For the angels']),
  (14,1,0,ARRAY['La résurrection de Jésus','Le don de la loi','La Pentecôte'],ARRAY['The resurrection of Jesus','The giving of the law','Pentecost']),
  (14,2,0,ARRAY['Ils étaient réunis pour rompre le pain et écouter Paul','Ils instauraient un nouveau jour de repos','Ils célébraient un mariage'],ARRAY['They met to break bread and listen to Paul','They set up a new day of rest','They celebrated a wedding']),
  (14,3,0,ARRAY['Changer les temps et la loi','Reconstruire le temple','Traduire les Écritures'],ARRAY['To change times and the law','To rebuild the temple','To translate the Scriptures']),
  (14,4,0,ARRAY['Obéir à Dieu plutôt qu''aux hommes','Suivre toujours l''autorité humaine','Se taire en toute circonstance'],ARRAY['Obey God rather than men','Always follow human authority','Stay silent in every case']),
  (15,1,0,ARRAY['Prier en secret, simplement, en s''adressant au Père','Prier longuement en public','Répéter des formules savantes'],ARRAY['Pray in secret, simply, addressing the Father','Pray at length in public','Repeat learned formulas']),
  (15,2,0,ARRAY['La paix de Dieu qui garde le cœur','La disparition immédiate des problèmes','La richesse matérielle'],ARRAY['The peace of God that guards the heart','The immediate end of all problems','Material wealth']),
  (15,3,0,ARRAY['Il nous écoute quand nous demandons selon sa volonté','Il exauce tous nos caprices','Il n''entend que les prêtres'],ARRAY['He hears us when we ask according to his will','He grants every whim','He hears only priests']),
  (15,4,0,ARRAY['Prier constamment, sans se lasser','Prier une fois par an','Prier seulement en cas de danger'],ARRAY['Pray always and do not give up','Pray once a year','Pray only in danger']),
  (16,1,0,ARRAY['De la poussière du sol et du souffle de vie','D''une âme immortelle indépendante du corps','De la lumière des étoiles'],ARRAY['Of dust from the ground and the breath of life','Of an immortal soul independent of the body','Of starlight']),
  (16,2,0,ARRAY['Ils ne savent rien ; leur activité a cessé','Ils observent les vivants','Ils souffrent consciemment'],ARRAY['They know nothing; their activity has ceased','They watch the living','They suffer consciously']),
  (16,3,0,ARRAY['Le sommeil','Le voyage','La fête'],ARRAY['Sleep','A journey','A feast']),
  (16,4,0,ARRAY['À la venue du Seigneur, au son de la trompette','Aussitôt après leur dernier souffle','Après mille ans de purification'],ARRAY['At the Lord''s coming, at the sound of the trumpet','Immediately after their last breath','After a thousand years of purification']),
  (17,1,0,ARRAY['Ils sont consumés, comme la paille par le feu','Ils brûlent sans fin','Ils règnent sur la terre'],ARRAY['They are consumed, like stubble in the fire','They burn without end','They reign over the earth']),
  (17,2,0,ARRAY['Le feu descend du ciel, après les mille ans','Le feu brûle depuis la création','Le feu vient du centre de la terre'],ARRAY['Fire comes down from heaven, after the thousand years','Fire has burned since creation','Fire comes from the centre of the earth']),
  (17,3,0,ARRAY['La mort — mais le don de Dieu est la vie éternelle','Une souffrance sans fin','Une simple maladie'],ARRAY['Death — but God''s gift is eternal life','Endless suffering','A mere illness']),
  (17,4,0,ARRAY['Qu''il se détourne de sa voie et qu''il vive','Qu''il périsse rapidement','Qu''il paie une amende'],ARRAY['That he turn from his way and live','That he perish quickly','That he pay a fine']),
  (18,1,0,ARRAY['Il est lié, sans personne à séduire','Il règne sur les nations','Il est détruit immédiatement'],ARRAY['He is bound, with no one left to deceive','He reigns over the nations','He is destroyed at once']),
  (18,2,0,ARRAY['Ils règnent et jugent avec Christ','Ils dorment encore','Ils reconstruisent la terre'],ARRAY['They reign and judge with Christ','They are still asleep','They rebuild the earth']),
  (18,3,0,ARRAY['À la fin des mille ans','Au début des mille ans','Jamais'],ARRAY['At the end of the thousand years','At the beginning of the thousand years','Never']),
  (18,4,0,ARRAY['Dévastée et vide d''habitants','Fleurie et peuplée','Couverte d''eau'],ARRAY['Ruined and empty of inhabitants','Blooming and populated','Covered with water']),
  (19,1,0,ARRAY['Le trône du jugement et les livres ouverts','Un festin de noces','La construction du temple'],ARRAY['The throne of judgement and the books opened','A wedding feast','The building of the temple']),
  (19,2,0,ARRAY['Toutes les œuvres, même cachées','Seules les paroles publiques','Seules les fautes des prêtres'],ARRAY['Every work, even hidden ones','Only public words','Only the faults of priests']),
  (19,3,0,ARRAY['Jésus-Christ, le juste','Un ange anonyme','Notre propre mérite'],ARRAY['Jesus Christ, the righteous one','An anonymous angel','Our own merit']),
  (19,4,0,ARRAY['Craindre Dieu, lui rendre gloire et adorer le Créateur','Se cacher et se taire','Payer un tribut au temple'],ARRAY['Fear God, give him glory and worship the Creator','Hide and keep silent','Pay a tribute to the temple']),
  (20,1,0,ARRAY['Garder les commandements de Dieu et la foi en Jésus','Bâtir de grands édifices','Se retirer du monde'],ARRAY['Keeping God''s commandments and faith in Jesus','Building great buildings','Withdrawing from the world']),
  (20,2,0,ARRAY['Les commandements de Dieu et la foi de Jésus','Les traditions des anciens','Le silence'],ARRAY['The commandments of God and the faith of Jesus','The traditions of the elders','Silence']),
  (20,3,0,ARRAY['Un seul corps, un seul Seigneur, une seule foi, un seul baptême','L''accord des gouvernements','L''uniformité des cultures'],ARRAY['One body, one Lord, one faith, one baptism','The agreement of governments','Uniformity of cultures']),
  (20,4,0,ARRAY['Ils examinaient chaque jour les Écritures','Ils croyaient sans vérifier','Ils refusaient d''écouter'],ARRAY['They searched the Scriptures daily','They believed without checking','They refused to listen']),
  (21,1,0,ARRAY['Par immersion : il est sorti de l''eau','Par aspersion, tout enfant','Sans eau, par la parole seule'],ARRAY['By immersion: he came up out of the water','By sprinkling, as an infant','Without water, by word alone']),
  (21,2,0,ARRAY['La mort au péché et la résurrection à une vie nouvelle','Une simple entrée dans une association','Une purification du corps'],ARRAY['Death to sin and rising to a new life','Simply joining an organisation','A cleansing of the body']),
  (21,3,0,ARRAY['La repentance, puis le baptême, et le don de l''Esprit','Un examen de connaissances','Une offrande obligatoire'],ARRAY['Repentance, then baptism, and the gift of the Spirit','An exam on knowledge','A required offering']),
  (21,4,0,ARRAY['Faire des disciples, baptiser et enseigner','Construire des temples','Rester entre soi'],ARRAY['Make disciples, baptise and teach','Build temples','Keep to ourselves']),
  (22,1,0,ARRAY['Dieu ouvre les écluses des cieux et bénit','Il exige davantage chaque année','Aucune promesse n''est faite'],ARRAY['God opens the windows of heaven and blesses','He demands more each year','No promise is made']),
  (22,2,0,ARRAY['Sans tristesse ni contrainte, avec joie','Par obligation','Pour être vu des autres'],ARRAY['Not reluctantly or under compulsion, but gladly','Out of obligation','To be seen by others']),
  (22,3,0,ARRAY['Il y a plus de bonheur à donner qu''à recevoir','Il faut d''abord s''enrichir','Chacun pour soi'],ARRAY['It is more blessed to give than to receive','You must get rich first','Everyone for themselves']),
  (22,4,0,ARRAY['Tout vient de Dieu ; nous rendons ce qu''il donne','Tout vient de notre travail','Tout vient du roi'],ARRAY['Everything comes from God; we return what he gives','Everything comes from our work','Everything comes from the king']),
  (23,1,0,ARRAY['Un temple du Saint-Esprit, racheté à un grand prix','Une possession sans importance','Un obstacle à la vie spirituelle'],ARRAY['A temple of the Holy Spirit, bought at a great price','An unimportant possession','An obstacle to spiritual life']),
  (23,2,0,ARRAY['Tout faire pour la gloire de Dieu','Suivre la mode','Rechercher son seul plaisir'],ARRAY['Do everything for the glory of God','Follow the fashion','Seek only our own pleasure']),
  (23,3,0,ARRAY['Les plantes portant semence et les fruits des arbres','Toute viande sans distinction','Un jeûne permanent'],ARRAY['Seed-bearing plants and the fruit of trees','Any meat without distinction','Permanent fasting']),
  (23,4,0,ARRAY['Qu''il prospère et soit en bonne santé, comme son âme','Qu''il devienne célèbre','Qu''il voyage beaucoup'],ARRAY['That he prosper and be in health, as his soul does','That he become famous','That he travel widely']),
  (24,1,0,ARRAY['À suivre les traces de Christ, même dans la souffrance','À éviter toute difficulté','À juger les autres'],ARRAY['To follow in Christ''s steps, even through suffering','To avoid all hardship','To judge others']),
  (24,2,0,ARRAY['Le service humble : se laver les pieds les uns des autres','La recherche des premières places','Le silence absolu'],ARRAY['Humble service: washing one another''s feet','Seeking the best seats','Absolute silence']),
  (24,3,0,ARRAY['Venez à moi, et vous trouverez du repos','Travaillez davantage','Attendez d''être parfaits'],ARRAY['Come to me, and you will find rest','Work harder','Wait until you are perfect']),
  (24,4,0,ARRAY['Dieu, qui a commencé cette œuvre en nous','Nous-mêmes, par nos efforts','L''Église seule'],ARRAY['God, who began that work in us','We ourselves, by our efforts','The church alone']),
  (25,1,0,ARRAY['Faire chaque choix pour la gloire de Dieu','Suivre l''avis de la majorité','Ne rien décider'],ARRAY['Make every choice for the glory of God','Follow the majority opinion','Decide nothing']),
  (25,2,0,ARRAY['Aimer, pardonner et servir comme lui','Imiter son habit','Vivre isolé du monde'],ARRAY['Loving, forgiving and serving as he did','Copying his clothing','Living cut off from the world']),
  (25,3,0,ARRAY['Choisir aujourd''hui de servir le Seigneur','Remettre la décision à plus tard','Laisser les autres choisir'],ARRAY['Choose today to serve the Lord','Put the decision off','Let others choose']),
  (25,4,0,ARRAY['En Christ qui nous fortifie','En nos propres ressources','Dans l''approbation des autres'],ARRAY['In Christ who strengthens us','In our own resources','In the approval of others'])
)
UPDATE public.lesson_questions q
SET options_fr = d.fr, options_en = d.en, correct_index = d.ci
FROM data d, public.lessons l
WHERE l.id = q.lesson_id AND l.position = d.lp AND q.position = d.qp;